// generated by build-games: content/games/<slug>.html -> bu fayl. Əl ilə dəyişmə; node scripts/build-games.mjs işlət.
export default "<!DOCTYPE html>\n<html lang=\"tr\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, user-scalable=no\">\n<title>NEON VOID — Premium Arcade</title>\n<style>\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n  html, body { width: 100%; height: 100%; overflow: hidden; background: #050508; }\n  body {\n    font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;\n    display: flex; align-items: center; justify-content: center;\n    background: radial-gradient(ellipse at 50% 120%, #1a0b2e 0%, #050508 60%);\n    touch-action: none; user-select: none; -webkit-user-select: none;\n  }\n  #wrap { position: relative; width: 100vw; height: 100vh; }\n  canvas { display: block; width: 100%; height: 100%; }\n\n  .overlay {\n    position: absolute; inset: 0; z-index: 10;\n    display: flex; flex-direction: column; align-items: center; justify-content: center;\n    background: rgba(5,5,8,.72); backdrop-filter: blur(14px);\n    transition: opacity .5s ease; text-align: center; padding: 24px;\n  }\n  .overlay.hidden { opacity: 0; pointer-events: none; }\n\n  .logo {\n    font-size: clamp(44px, 10vw, 96px); font-weight: 900; letter-spacing: .12em;\n    background: linear-gradient(180deg, #fff 0%, #a855f7 55%, #22d3ee 100%);\n    -webkit-background-clip: text; background-clip: text; color: transparent;\n    filter: drop-shadow(0 0 30px rgba(168,85,247,.55));\n    animation: float 3.2s ease-in-out infinite;\n  }\n  @keyframes float { 0%,100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }\n\n  .tagline {\n    margin-top: 10px; color: #8b8ba3; font-size: clamp(13px, 2.4vw, 16px);\n    letter-spacing: .35em; text-transform: uppercase;\n  }\n  .btn {\n    margin-top: 42px; padding: 16px 58px; font-size: 18px; font-weight: 700;\n    letter-spacing: .2em; text-transform: uppercase; color: #050508;\n    background: linear-gradient(90deg, #22d3ee, #a855f7);\n    border: none; border-radius: 999px; cursor: pointer;\n    box-shadow: 0 0 32px rgba(34,211,238,.45), 0 0 64px rgba(168,85,247,.25);\n    transition: transform .15s ease, box-shadow .15s ease;\n  }\n  .btn:hover { transform: scale(1.06); box-shadow: 0 0 48px rgba(34,211,238,.7), 0 0 96px rgba(168,85,247,.4); }\n  .btn:active { transform: scale(.97); }\n\n  .hint { margin-top: 26px; color: #55556e; font-size: 13px; letter-spacing: .1em; line-height: 1.9; }\n  .hint b { color: #9d9dbd; }\n\n  #gameover .logo {\n    background: linear-gradient(180deg, #fff 0%, #f43f5e 55%, #f97316 100%);\n    -webkit-background-clip: text; background-clip: text;\n    filter: drop-shadow(0 0 30px rgba(244,63,94,.5));\n  }\n  .score-big { margin-top: 18px; font-size: clamp(36px, 8vw, 64px); font-weight: 800; color: #fff; text-shadow: 0 0 24px rgba(34,211,238,.6); }\n  .score-label { color: #8b8ba3; letter-spacing: .3em; font-size: 12px; text-transform: uppercase; margin-top: 4px; }\n  #best { margin-top: 10px; color: #fbbf24; font-size: 15px; letter-spacing: .15em; }\n  #newbest { display: none; margin-top: 8px; color: #4ade80; font-weight: 700; letter-spacing: .25em; font-size: 13px; animation: pulse 1s infinite; }\n  @keyframes pulse { 50% { opacity: .4; } }\n\n  #hud {\n    position: absolute; top: 0; left: 0; right: 0; z-index: 5;\n    display: flex; justify-content: space-between; align-items: flex-start;\n    padding: 18px 22px; pointer-events: none; opacity: 0; transition: opacity .4s;\n  }\n  #hud.on { opacity: 1; }\n  .hud-score { font-size: 30px; font-weight: 800; color: #fff; text-shadow: 0 0 16px rgba(34,211,238,.7); font-variant-numeric: tabular-nums; }\n  .hud-label { font-size: 10px; letter-spacing: .3em; color: #8b8ba3; text-transform: uppercase; }\n  #lives { display: flex; gap: 6px; margin-top: 6px; justify-content: flex-end; }\n  .life { width: 14px; height: 14px; transform: rotate(45deg); background: linear-gradient(135deg, #f43f5e, #fb7185); box-shadow: 0 0 10px rgba(244,63,94,.8); border-radius: 3px; transition: opacity .3s, transform .3s; }\n  .life.lost { opacity: .15; transform: rotate(45deg) scale(.7); box-shadow: none; }\n  #combo { position: absolute; top: 84px; left: 50%; transform: translateX(-50%); font-size: 22px; font-weight: 800; color: #fbbf24; text-shadow: 0 0 18px rgba(251,191,36,.8); opacity: 0; transition: opacity .2s; letter-spacing: .1em; }\n  #muteBtn { position: absolute; bottom: 16px; right: 16px; z-index: 20; background: rgba(255,255,255,.06); border: 1px solid rgba(255,255,255,.12); color: #9d9dbd; width: 44px; height: 44px; border-radius: 12px; font-size: 18px; cursor: pointer; backdrop-filter: blur(6px); }\n</style>\n</head>\n<body>\n<div id=\"wrap\">\n  <canvas id=\"game\"></canvas>\n\n  <div id=\"hud\">\n    <div>\n      <div class=\"hud-label\">Skor</div>\n      <div class=\"hud-score\" id=\"score\">0</div>\n    </div>\n    <div style=\"text-align:right\">\n      <div class=\"hud-label\">Can</div>\n      <div id=\"lives\"></div>\n    </div>\n  </div>\n  <div id=\"combo\"></div>\n\n  <div class=\"overlay\" id=\"menu\">\n    <div class=\"logo\">NEON VOID</div>\n    <div class=\"tagline\">Premium Arcade Deneyimi</div>\n    <button class=\"btn\" id=\"startBtn\">Başla</button>\n    <div class=\"hint\">\n      <b>← →</b> veya <b>A / D</b> ile hareket et &nbsp;•&nbsp; Mobilde parmağını sürükle<br>\n      Kristalleri topla, meteorlardan kaçın. Kombo yap, skoru katla!\n    </div>\n  </div>\n\n  <div class=\"overlay hidden\" id=\"gameover\">\n    <div class=\"logo\">OYUN BİTTİ</div>\n    <div class=\"score-big\" id=\"finalScore\">0</div>\n    <div class=\"score-label\">Final Skoru</div>\n    <div id=\"best\">En İyi: 0</div>\n    <div id=\"newbest\">★ YENİ REKOR ★</div>\n    <button class=\"btn\" id=\"retryBtn\">Tekrar Oyna</button>\n  </div>\n\n  <button id=\"muteBtn\" title=\"Ses\">🔊</button>\n</div>\n\n<script>\n(() => {\n  \"use strict\";\n  const canvas = document.getElementById(\"game\");\n  const ctx = canvas.getContext(\"2d\");\n  let W = 0, H = 0, DPR = Math.min(window.devicePixelRatio || 1, 2);\n\n  function resize() {\n    W = window.innerWidth; H = window.innerHeight;\n    canvas.width = W * DPR; canvas.height = H * DPR;\n    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);\n  }\n  window.addEventListener(\"resize\", resize);\n  resize();\n\n  // ---------- SES (WebAudio, dosyasız) ----------\n  let audioCtx = null, muted = false;\n  function ac() {\n    if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();\n    if (audioCtx.state === \"suspended\") audioCtx.resume();\n    return audioCtx;\n  }\n  function tone(freq, dur, type, vol, slide) {\n    if (muted) return;\n    try {\n      const a = ac(), o = a.createOscillator(), g = a.createGain();\n      o.type = type || \"sine\"; o.frequency.setValueAtTime(freq, a.currentTime);\n      if (slide) o.frequency.exponentialRampToValueAtTime(slide, a.currentTime + dur);\n      g.gain.setValueAtTime(vol || 0.15, a.currentTime);\n      g.gain.exponentialRampToValueAtTime(0.0001, a.currentTime + dur);\n      o.connect(g); g.connect(a.destination);\n      o.start(); o.stop(a.currentTime + dur);\n    } catch (e) {}\n  }\n  const sfx = {\n    pickup: (c) => { tone(500 + Math.min(c, 20) * 40, 0.12, \"sine\", 0.14, 900 + c * 40); },\n    hit:    () => { tone(160, 0.35, \"sawtooth\", 0.22, 40); tone(90, 0.4, \"square\", 0.12, 30); },\n    start:  () => { tone(220, 0.15, \"sine\", 0.15, 440); setTimeout(() => tone(440, 0.2, \"sine\", 0.15, 880), 120); },\n    over:   () => { tone(400, 0.5, \"sawtooth\", 0.18, 60); },\n  };\n  document.getElementById(\"muteBtn\").addEventListener(\"click\", (e) => {\n    muted = !muted; e.target.textContent = muted ? \"🔇\" : \"🔊\";\n  });\n\n  // ---------- DURUM ----------\n  const STATE = { MENU: 0, PLAY: 1, OVER: 2 };\n  let state = STATE.MENU;\n  let score = 0, best = +(localStorage.getItem(\"neonvoid_best\") || 0);\n  let lives = 3, combo = 0, comboTimer = 0, invuln = 0, shake = 0, time = 0;\n  let difficulty = 1;\n\n  const ship = { x: 0, y: 0, vx: 0, w: 46, h: 34, targetX: null };\n  const keys = {};\n  let gems = [], rocks = [], parts = [], stars = [];\n\n  // Yıldız arka planı\n  for (let i = 0; i < 120; i++) {\n    stars.push({ x: Math.random(), y: Math.random(), z: Math.random() * 0.8 + 0.2, s: Math.random() * 1.8 + 0.4 });\n  }\n\n  function reset() {\n    score = 0; lives = 3; combo = 0; comboTimer = 0; invuln = 120; shake = 0; difficulty = 1;\n    gems = []; rocks = []; parts = [];\n    ship.x = W / 2; ship.y = H - 110; ship.vx = 0; ship.targetX = null;\n    updateHUD();\n  }\n\n  function updateHUD() {\n    document.getElementById(\"score\").textContent = score;\n    const lv = document.getElementById(\"lives\");\n    lv.innerHTML = \"\";\n    for (let i = 0; i < 3; i++) {\n      const d = document.createElement(\"div\");\n      d.className = \"life\" + (i < lives ? \"\" : \" lost\");\n      lv.appendChild(d);\n    }\n  }\n\n  function showCombo() {\n    const el = document.getElementById(\"combo\");\n    if (combo >= 3) {\n      el.textContent = \"KOMBO x\" + combo;\n      el.style.opacity = 1;\n      clearTimeout(el._t);\n      el._t = setTimeout(() => el.style.opacity = 0, 700);\n    }\n  }\n\n  // ---------- OLUŞTURUCULAR ----------\n  function spawnGem() {\n    gems.push({\n      x: 30 + Math.random() * (W - 60), y: -30,\n      vy: (1.6 + Math.random() * 1.4) * difficulty,\n      r: 13, rot: Math.random() * Math.PI * 2, vr: (Math.random() - .5) * .1,\n      hue: Math.random() < .5 ? 185 : 285,\n    });\n  }\n  function spawnRock() {\n    const r = 16 + Math.random() * 22;\n    rocks.push({\n      x: r + Math.random() * (W - r * 2), y: -r - 10,\n      vy: (2 + Math.random() * 2.2) * difficulty,\n      vx: (Math.random() - .5) * 1.4,\n      r, rot: Math.random() * Math.PI * 2, vr: (Math.random() - .5) * .08,\n      verts: Array.from({ length: 9 }, () => 0.72 + Math.random() * 0.5),\n    });\n  }\n  function burst(x, y, color, n, pow) {\n    for (let i = 0; i < n; i++) {\n      const a = Math.random() * Math.PI * 2, sp = (Math.random() * 0.7 + 0.3) * (pow || 4);\n      parts.push({ x, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp, life: 1, decay: 0.02 + Math.random() * 0.03, color, size: Math.random() * 3.5 + 1.5 });\n    }\n  }\n\n  // ---------- GİRİŞ ----------\n  window.addEventListener(\"keydown\", (e) => {\n    keys[e.key.toLowerCase()] = true;\n    if (state !== STATE.PLAY && (e.key === \" \" || e.key === \"Enter\")) startGame();\n  });\n  window.addEventListener(\"keyup\", (e) => keys[e.key.toLowerCase()] = false);\n\n  function pointerX(e) {\n    const t = e.touches ? e.touches[0] : e;\n    return t.clientX;\n  }\n  canvas.addEventListener(\"pointermove\", (e) => { if (state === STATE.PLAY) ship.targetX = e.clientX; });\n  canvas.addEventListener(\"pointerdown\", (e) => { if (state === STATE.PLAY) ship.targetX = e.clientX; });\n  canvas.addEventListener(\"touchmove\", (e) => { e.preventDefault(); if (state === STATE.PLAY) ship.targetX = pointerX(e); }, { passive: false });\n  canvas.addEventListener(\"touchstart\", (e) => { if (state === STATE.PLAY) ship.targetX = pointerX(e); }, { passive: true });\n\n  // ---------- OYUN AKIŞI ----------\n  function startGame() {\n    reset();\n    state = STATE.PLAY;\n    document.getElementById(\"menu\").classList.add(\"hidden\");\n    document.getElementById(\"gameover\").classList.add(\"hidden\");\n    document.getElementById(\"hud\").classList.add(\"on\");\n    sfx.start();\n  }\n  function endGame() {\n    state = STATE.OVER;\n    sfx.over();\n    const isNew = score > best;\n    if (isNew) { best = score; localStorage.setItem(\"neonvoid_best\", best); }\n    document.getElementById(\"finalScore\").textContent = score;\n    document.getElementById(\"best\").textContent = \"En İyi: \" + best;\n    document.getElementById(\"newbest\").style.display = isNew && score > 0 ? \"block\" : \"none\";\n    document.getElementById(\"hud\").classList.remove(\"on\");\n    setTimeout(() => document.getElementById(\"gameover\").classList.remove(\"hidden\"), 500);\n  }\n  document.getElementById(\"startBtn\").addEventListener(\"click\", startGame);\n  document.getElementById(\"retryBtn\").addEventListener(\"click\", startGame);\n\n  // ---------- GÜNCELLE ----------\n  let spawnG = 0, spawnR = 0;\n  function update(dt) {\n    time += dt;\n    difficulty = 1 + Math.min(score / 400, 2.2);\n\n    // Gemi\n    const speed = 9;\n    if (keys[\"arrowleft\"] || keys[\"a\"]) { ship.vx = -speed; ship.targetX = null; }\n    else if (keys[\"arrowright\"] || keys[\"d\"]) { ship.vx = speed; ship.targetX = null; }\n    else if (ship.targetX != null) {\n      const dx = ship.targetX - ship.x;\n      ship.vx = Math.max(-speed * 1.4, Math.min(speed * 1.4, dx * 0.18));\n      if (Math.abs(dx) < 3) ship.vx = 0;\n    } else ship.vx *= 0.82;\n    ship.x = Math.max(ship.w / 2, Math.min(W - ship.w / 2, ship.x + ship.vx));\n\n    // Üretim\n    spawnG -= dt; spawnR -= dt;\n    if (spawnG <= 0) { spawnGem(); spawnG = Math.max(0.35, 0.9 - difficulty * 0.12); }\n    if (spawnR <= 0) { spawnRock(); spawnR = Math.max(0.4, 1.3 - difficulty * 0.22); }\n\n    // Kristaller\n    for (let i = gems.length - 1; i >= 0; i--) {\n      const g = gems[i];\n      g.y += g.vy; g.rot += g.vr;\n      const dx = g.x - ship.x, dy = g.y - ship.y;\n      if (Math.abs(dx) < ship.w / 2 + g.r && Math.abs(dy) < ship.h / 2 + g.r) {\n        combo++; comboTimer = 2.2;\n        const gain = 10 * Math.min(combo, 10);\n        score += gain;\n        burst(g.x, g.y, \"hsl(\" + g.hue + \",100%,65%)\", 16, 4);\n        sfx.pickup(combo);\n        showCombo();\n        gems.splice(i, 1);\n        updateHUD();\n        continue;\n      }\n      if (g.y > H + 40) { gems.splice(i, 1); if (combo > 0) { combo = 0; } }\n    }\n    if (comboTimer > 0) { comboTimer -= dt; if (comboTimer <= 0) combo = 0; }\n\n    // Meteorlar\n    for (let i = rocks.length - 1; i >= 0; i--) {\n      const r = rocks[i];\n      r.y += r.vy; r.x += r.vx; r.rot += r.vr;\n      if (r.x < r.r || r.x > W - r.r) r.vx *= -1;\n      const dx = r.x - ship.x, dy = r.y - ship.y;\n      const dist = Math.hypot(dx, dy);\n      if (invuln <= 0 && dist < r.r * 0.82 + ship.w * 0.36) {\n        lives--; combo = 0; invuln = 110; shake = 22;\n        burst(ship.x, ship.y, \"#f43f5e\", 34, 7);\n        burst(r.x, r.y, \"#f97316\", 20, 5);\n        sfx.hit();\n        rocks.splice(i, 1);\n        updateHUD();\n        if (lives <= 0) { endGame(); return; }\n        continue;\n      }\n      if (r.y > H + 60) rocks.splice(i, 1);\n    }\n\n    // Parçacıklar\n    for (let i = parts.length - 1; i >= 0; i--) {\n      const p = parts[i];\n      p.x += p.vx; p.y += p.vy; p.vy += 0.05; p.life -= p.decay;\n      if (p.life <= 0) parts.splice(i, 1);\n    }\n\n    if (invuln > 0) invuln--;\n    if (shake > 0) shake *= 0.88;\n  }\n\n  // ---------- ÇİZ ----------\n  function drawShip() {\n    const blink = invuln > 0 && Math.floor(time * 14) % 2 === 0;\n    ctx.save();\n    ctx.translate(ship.x, ship.y);\n    ctx.rotate(ship.vx * 0.03);\n    if (blink) ctx.globalAlpha = 0.35;\n\n    // Motor alevi\n    const fl = 14 + Math.sin(time * 30) * 5 + Math.abs(ship.vx) * 1.2;\n    const fg = ctx.createLinearGradient(0, ship.h / 2, 0, ship.h / 2 + fl + 14);\n    fg.addColorStop(0, \"rgba(34,211,238,.95)\");\n    fg.addColorStop(1, \"rgba(168,85,247,0)\");\n    ctx.fillStyle = fg;\n    ctx.beginPath();\n    ctx.moveTo(-8, ship.h / 2 - 4);\n    ctx.lineTo(0, ship.h / 2 + fl + 12);\n    ctx.lineTo(8, ship.h / 2 - 4);\n    ctx.closePath(); ctx.fill();\n\n    // Gövde\n    const bg = ctx.createLinearGradient(0, -ship.h / 2, 0, ship.h / 2);\n    bg.addColorStop(0, \"#e0f2fe\");\n    bg.addColorStop(0.5, \"#22d3ee\");\n    bg.addColorStop(1, \"#7c3aed\");\n    ctx.fillStyle = bg;\n    ctx.shadowColor = \"rgba(34,211,238,.8)\"; ctx.shadowBlur = 22;\n    ctx.beginPath();\n    ctx.moveTo(0, -ship.h / 2);\n    ctx.lineTo(ship.w / 2, ship.h / 2);\n    ctx.lineTo(ship.w / 5, ship.h / 2 - 8);\n    ctx.lineTo(-ship.w / 5, ship.h / 2 - 8);\n    ctx.lineTo(-ship.w / 2, ship.h / 2);\n    ctx.closePath(); ctx.fill();\n    ctx.shadowBlur = 0;\n\n    // Kokpit\n    ctx.fillStyle = \"rgba(255,255,255,.9)\";\n    ctx.beginPath(); ctx.ellipse(0, -4, 5, 9, 0, 0, Math.PI * 2); ctx.fill();\n    ctx.restore();\n  }\n\n  function drawGem(g) {\n    ctx.save();\n    ctx.translate(g.x, g.y);\n    ctx.rotate(g.rot);\n    const c = \"hsl(\" + g.hue + \",100%,65%)\";\n    ctx.shadowColor = c; ctx.shadowBlur = 18;\n    const grad = ctx.createLinearGradient(-g.r, -g.r, g.r, g.r);\n    grad.addColorStop(0, \"#fff\");\n    grad.addColorStop(0.4, c);\n    grad.addColorStop(1, \"hsl(\" + g.hue + \",90%,40%)\");\n    ctx.fillStyle = grad;\n    ctx.beginPath();\n    ctx.moveTo(0, -g.r); ctx.lineTo(g.r * .8, 0); ctx.lineTo(0, g.r); ctx.lineTo(-g.r * .8, 0);\n    ctx.closePath(); ctx.fill();\n    ctx.shadowBlur = 0;\n    ctx.fillStyle = \"rgba(255,255,255,.75)\";\n    ctx.beginPath();\n    ctx.moveTo(0, -g.r * .55); ctx.lineTo(g.r * .35, 0); ctx.lineTo(0, g.r * .25); ctx.lineTo(-g.r * .35, 0);\n    ctx.closePath(); ctx.fill();\n    ctx.restore();\n  }\n\n  function drawRock(r) {\n    ctx.save();\n    ctx.translate(r.x, r.y);\n    ctx.rotate(r.rot);\n    ctx.shadowColor = \"rgba(249,115,22,.5)\"; ctx.shadowBlur = 12;\n    const grad = ctx.createRadialGradient(-r.r * .3, -r.r * .3, r.r * .1, 0, 0, r.r);\n    grad.addColorStop(0, \"#57534e\");\n    grad.addColorStop(0.7, \"#292524\");\n    grad.addColorStop(1, \"#1c1917\");\n    ctx.fillStyle = grad;\n    ctx.beginPath();\n    for (let i = 0; i < r.verts.length; i++) {\n      const a = (i / r.verts.length) * Math.PI * 2;\n      const rr = r.r * r.verts[i];\n      i === 0 ? ctx.moveTo(Math.cos(a) * rr, Math.sin(a) * rr) : ctx.lineTo(Math.cos(a) * rr, Math.sin(a) * rr);\n    }\n    ctx.closePath(); ctx.fill();\n    ctx.shadowBlur = 0;\n    ctx.strokeStyle = \"rgba(249,115,22,.35)\"; ctx.lineWidth = 1.5; ctx.stroke();\n    ctx.restore();\n  }\n\n  function draw() {\n    ctx.clearRect(0, 0, W, H);\n    ctx.save();\n    if (shake > 0.5) ctx.translate((Math.random() - .5) * shake, (Math.random() - .5) * shake);\n\n    // Yıldızlar\n    for (const s of stars) {\n      s.y += 0.0006 * s.z * (state === STATE.PLAY ? difficulty : 0.4);\n      if (s.y > 1) s.y = 0;\n      ctx.globalAlpha = 0.25 + s.z * 0.6;\n      ctx.fillStyle = \"#c7d2fe\";\n      ctx.fillRect(s.x * W, s.y * H, s.s, s.s);\n    }\n    ctx.globalAlpha = 1;\n\n    if (state === STATE.PLAY || state === STATE.OVER) {\n      for (const g of gems) drawGem(g);\n      for (const r of rocks) drawRock(r);\n      for (const p of parts) {\n        ctx.globalAlpha = Math.max(p.life, 0);\n        ctx.fillStyle = p.color;\n        ctx.beginPath(); ctx.arc(p.x, p.y, p.size * p.life, 0, Math.PI * 2); ctx.fill();\n      }\n      ctx.globalAlpha = 1;\n      if (state === STATE.PLAY) drawShip();\n    } else {\n      // Menüde süs gemisi\n      ship.x = W / 2 + Math.sin(time * 0.8) * 60;\n      ship.y = H * 0.72 + Math.sin(time * 1.7) * 10;\n      ship.vx = Math.cos(time * 0.8) * 4;\n      drawShip();\n    }\n    ctx.restore();\n\n    // Vinyet\n    const v = ctx.createRadialGradient(W / 2, H / 2, Math.min(W, H) * 0.35, W / 2, H / 2, Math.max(W, H) * 0.75);\n    v.addColorStop(0, \"rgba(0,0,0,0)\");\n    v.addColorStop(1, \"rgba(0,0,0,.5)\");\n    ctx.fillStyle = v;\n    ctx.fillRect(0, 0, W, H);\n  }\n\n  // ---------- DÖNGÜ ----------\n  let last = performance.now();\n  function loop(now) {\n    const dt = Math.min((now - last) / 1000, 0.05);\n    last = now;\n    if (state === STATE.PLAY) update(dt); else time += dt;\n    draw();\n    requestAnimationFrame(loop);\n  }\n  requestAnimationFrame(loop);\n})();\n</script>\n</body>\n</html>\n";
